import json
n=28
sep={4,9,14,19,24}
grid=[[8 if r in sep or c in sep else 0 for c in range(n)] for r in range(n)]
# bands from separator positions
bands=[]
start=0
for i in range(n):
    if i in sep:
        if start<i: bands.append(list(range(start,i)))
        start=i+1
if start<n: bands.append(list(range(start,n)))
# Color block cells in row-band 1 with 2, col-band 0 with 2, col-band 2 with 3
for bi,rs in enumerate(bands):
    for bj,cs in enumerate(bands):
        val=0
        if bi==1 or bj==0: val=2
        if bj==2: val=3
        if bi==1 and bj==2: val=6
        if val:
            for r in rs:
                for c in cs: grid[r][c]=val
print(json.dumps(grid,separators=(',',':')))

